<script setup lang="ts">
import {computed,onBeforeUnmount,ref} from 'vue';
import {gpsReport,type GpsSample} from './gps.ts';
const gate=ref<'main'|'second'>('main'),witnessed=ref(false),samples=ref<GpsSample[]>([]),message=ref(''),recording=ref(false);let watch:number|undefined,timer:ReturnType<typeof setTimeout>|undefined;
const result=computed(()=>gpsReport(samples.value,gate.value,witnessed.value));
function stop(){if(watch!==undefined)navigator.geolocation.clearWatch(watch);watch=undefined;clearTimeout(timer);recording.value=false;}
function start(){stop();samples.value=[];message.value='Recording locally for up to 90 seconds. Stay stationary in an accessible place beside the gate, away from traffic.';if(!navigator.geolocation){message.value='Geolocation unavailable. Use your phone GPS app and record WGS84 longitude, latitude, accuracy and UTC time.';return;}recording.value=true;watch=navigator.geolocation.watchPosition(p=>{samples.value.push({longitude:p.coords.longitude,latitude:p.coords.latitude,accuracy:p.coords.accuracy,timestamp:p.timestamp});if(samples.value.length>=120)stop();},e=>{message.value=e.message+' No location was uploaded.';stop();},{enableHighAccuracy:true,maximumAge:0,timeout:20000});timer=setTimeout(stop,90000);}
function download(){const blob=new Blob([JSON.stringify(result.value,null,2)],{type:'application/geo+json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`fuw-${gate.value}-gate-field-report.geojson`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
onBeforeUnmount(stop);
</script>
<template><details class="gps"><summary>Record a firsthand gate GPS report</summary><p>Use a phone outdoors only where you are permitted to stand. Record the main and second gates separately. Do not measure while in a vehicle or use a map pin. This button requests device location only when pressed; nothing is uploaded or automatically added to the map.</p><label>Gate <select v-model="gate" :disabled="recording"><option value="main">Main gate</option><option value="second">Second gate</option></select></label><label><input type="checkbox" v-model="witnessed">I am physically at this identified entrance</label><button @click="recording?stop():start()">{{recording?'Stop GPS recording':'Start GPS recording'}}</button><p>{{message}}</p><p>Samples: {{samples.length}} / usable (reported accuracy ≤15m): {{result.features[0]?.properties.usableSamples??0}}. Aim for ten usable readings over at least30 seconds, then repeat independently.</p><pre v-if="result.features.length">{{JSON.stringify(result.features[0],null,2)}}</pre><button :disabled="!samples.length||recording" @click="download">Export local GPS report</button><p>Ask Physical Planning to corroborate the entrance identity, road connection and a clear virtual walking area. Share the exported file deliberately; GPS reports can reveal your location. On a phone, use a secure HTTPS origin or a GPS app; a laptop's localhost address does not open on another device automatically.</p></details></template>
<style scoped>.gps{border-top:1px solid #bac9ad;padding:12px 0}.gps label{display:block;margin:10px 0}.gps pre{white-space:pre-wrap;font-size:10px}.gps button,.gps select{min-height:42px;padding:8px;margin:4px;border:1px solid #a6b69d;border-radius:6px;background:#e6eedf}</style>
